street = max(streetx,streety);
street = max(street,streetr);

uv2 = (2*uv-0.35).yx;
float3 copy = GetPixel(uv2);
ret.r = lerp (0.05,copy,0.55) ;


//horizontale Fahrtrichtung
uv3 = uv_orig*texsize.xy*texsize_noise_lq.zw*float2(0.5,1);
uv3.x += (int(uv_orig.y*texsize_noise_lq.y)%8-4)*time*.015;
ret.b =  ((1*tex2D (sampler_pw_noise_lq, uv3).r) > 0.94)* (streety>slim) ;;

//vertikale Fahrtrichtung
uv3 = uv_orig*texsize.xy*texsize_noise_lq.zw*float2(1,0.5);
uv3.y += (int(uv_orig.x*texsize_noise_lq.x)%8-4)*time*.023;
ret.b +=  ((1*tex2D (sampler_pw_noise_lq, uv3).r) > 0.94)* (streetx>slim) ;;


//Kreisverkehr
uv3 = float2 (rad/aspect.y*1.07, ang/4*2);
uv3.y += (int(uv3.x*32-12))*0.023*time;
ret.b +=  ((1*tex2D (sampler_pw_noise_lq, uv3).r) > 0.94) *(streetr>slim) * 0.8;;


//Lichter
ret.b += (frac(32*ret.r+q1+0.5*tex2D(sampler_pw_noise_lq,uv/2).r)>0.83) *0.8* !street *(ret.r < 0.12);

ret.b += 0.1*street + 0.04;
ret.b = max (ret.b*1, GetPixel(uv_orig).b *0.74);
ret.r = ret.r*(1-street) ;


}

presetParts.comp:
sampler sampler_pw_noise_lq;
static const float quality = 5, depth = q30, z0=4;
static const float scale = 1.0/quality*depth/z0, d = length(texsize.zw);
float3 rsl, rsl0, rsl2, screen3, lights, lightcol, modmask;
float  lprof,dy, dy0, lav_gnd, laser, lg, tmp;
static const float3 mov = float3 (q5,q6, q7);
static const float3 t = float3(q14,q15,q16), s = float3(q17,q18,q19);
static const float3 ts = -cross(s,t), pos = float3 (q11,q12,q13);
static float2x3 tst = float2x3(ts,t);

float3 project (float gnd) {  float z;
  z = -1/mul(cross(ts,-t),screen3) -gnd ;
  return z*float3(mul(tst,cross(pos,screen3))*aspect.yx,1);}

shader_body {
//screen3 = float3 ((uv-float2(.5,.2))*aspect.xy,1.05-rad*rad/8);
screen3 = float3 ((uv-float2(.5,.3))*aspect.xy,1);
rsl0 = project (-depth) + mov;

lg = -0.001; //Unsinn, aber 5fps schneller als lg=0
for (int m=0; m < 4; m++) {
  rsl2 = (project (lg)+mov);
  tmp = 0.9/length (cross(pos,screen3))* (length ((frac(rsl2.xy) -0.5)));
  lg += tmp;
}
laser = 0.0015/tmp ;

modmask = tex2D(sampler_noise_hq,rsl0.xy*.05);
lav_gnd = 0;
for (int m=0; m <= quality; m++) {
  rsl = (project (lav_gnd)+mov);
  lprof = floor(z0*1-2*z0*GetPixel(rsl.xy).r )*scale ;
  lav_gnd -= lprof;
}
rsl = project (lav_gnd)+ mov; 
float streetlevel = saturate(-10*depth-12*lav_gnd);
float cmask = streetlevel > .01;

lightcol = lerp (tex2D (sampler_noise_hq,rsl.xy/6), 0.5, 0.2);
lights = .07/length(cos(rsl.xy*24+modmask.yx*2))* lightcol;
dy = GetPixel(rsl.xy+d) - GetPixel(rsl.xy-d); dy0 = dy;
dy += (GetPixel(rsl*2+d) - GetPixel(rsl*2-d))/2 * !cmask;
ret = max(0,dy)*lights* (3+modmask.z*4);
ret += lights*saturate(0.4-6*lav_gnd*modmask.y)*4;

ret += (.6+ret)*1*GetBlur1(frac(rsl0.xy)).b *saturate(streetlevel*2);

float3 car = GetPixel(frac(rsl0.xy)).b;
if (GetPixel(rsl0.xy).r >0.02) {car *= tex2D(sampler_noise_lq,rsl0.xy*2);};
ret += car * cmask;

float2 tmp2 =  sin(2*(rsl0.xy+.1*q4*(rand_frame.xy-0.5))+dy);
float flash = saturate(.01/length(tmp2));
ret += flash*saturate(1-6*lav_gnd)* q4 * float3(0.2,.5,1) ;

ret += 8*GetBlur1(frac(rsl.xy)).g * (0.1+ret)*saturate(1-8*lav_gnd);

//uncomment this line to disable lasers for higher performance
ret += (laser)* saturate(1.5-lg) * float3 (q21,q22,q23);;
//ret = GetPixel(uv);

}

